head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// 화면(DOM)에만 표시할 임시값 — DataList 원본과 형태는 같고 값만 다르다
scwin.FAKE_MAP = {
    "name"   : ["태블릿", "프린터", "스피커", "웹캠"],
    "region" : ["인천", "대구", "울산", "수원"],
    "qty"    : ["11", "22", "33", "44"],
    "total"  : ["11,000", "22,000", "33,000", "44,000"]
};

// 특정 Cell 의 화면 표시 텍스트 조회
scwin.getCellText = function (nRow, nCol) {
    var objTd = document.querySelector("td[id*='target1_cell_" + nRow + "_" + nCol + "']");
    return objTd ? (objTd.textContent || "").trim() : "";
};

// 특정 Column 의 모든 Row 화면 표시 텍스트를 배열로 조회
scwin.getColumnTexts = function (nCol) {
    var objGrid = $p.getComponentById("target1");
    var nCnt = objGrid.getRowCount();
    var arr = [];
    for (var r = 0; r < nCnt; r++) {
        arr.push(scwin.getCellText(r, nCol));
    }
    return arr;
};

// 특정 Row 의 모든 Column 화면 표시 텍스트를 배열로 조회
scwin.getRowTexts = function (nRow) {
    var objGrid = $p.getComponentById("target1");
    var nCnt = objGrid.getColumnCount();
    var arr = [];
    for (var c = 0; c < nCnt; c++) {
        arr.push(scwin.getCellText(nRow, c));
    }
    return arr;
};

// [1단계] DataList 는 그대로 두고 그리드 셀의 화면 표시값만 임시값으로 바꾼다 (화면과 DataList 불일치 상태)
scwin.btn_modifyCells_onclick = function (e) {
    var objGrid = $p.getComponentById("target1");
    var nRowCnt = objGrid.getRowCount();
    var nColCnt = objGrid.getColumnCount();

    for (var r = 0; r < nRowCnt; r++) {
        for (var c = 0; c < nColCnt; c++) {
            var objTd = document.querySelector("td[id*='target1_cell_" + r + "_" + c + "']");
            if (!objTd) { continue; }
            var strColId = objGrid.getColumnID(c);
            var arrFake = scwin.FAKE_MAP[strColId];
            objTd.textContent = (arrFake && typeof arrFake[r] !== "undefined") ? arrFake[r] : ("임시" + r);
        }
    }

    scwin.setReturnValue("[화면 값만 수정] DataList 는 원본 유지, 화면 표시값만 임시값으로 변경");
    scwin.setReturnValue("[화면 값만 수정] 수정 후 화면 표시값 - name : " + scwin.getColumnTexts(0).join(", ")
        + " / region : " + scwin.getColumnTexts(1).join(", ")
        + " / qty : " + scwin.getColumnTexts(2).join(", "));
};

// [2단계] 선택한 파라미터로 redrawColumn / refreshColumn 을 호출하고 해당 Column 의 화면 표시값을 출력
scwin.runColumnMethod = function (strMethod) {
    var objGrid = $p.getComponentById("target1");
    var strPar = $p.getComponentById("par_columnInfo").getValue();
    var parValue = (strPar === "name") ? "name" : Number(strPar);
    var nColIdx = (strPar === "name") ? 0 : Number(strPar);

    objGrid[strMethod](parValue);

    scwin.setReturnValue("[" + strMethod + "(" + (typeof parValue === "string" ? "'" + parValue + "'" : parValue) + ")]"
        + " 호출 후 화면 표시값 : " + scwin.getColumnTexts(nColIdx).join(", "));
};

scwin.btn_redrawColumn_onclick = function (e) {
    scwin.runColumnMethod("redrawColumn");
};

scwin.btn_refreshColumn_onclick = function (e) {
    scwin.runColumnMethod("refreshColumn");
};

// [2단계] refreshRow(0) 을 호출하고 Row 0 의 화면 표시값을 출력
scwin.btn_refreshRow_onclick = function (e) {
    var objGrid = $p.getComponentById("target1");

    objGrid.refreshRow(0);

    scwin.setReturnValue("[refreshRow(0)] 호출 후 Row 0 화면 표시값 : " + scwin.getRowTexts(0).join(", "));
};
